 "content": "def transform(grid):
    out=[r[:] for r in grid]
    h,w=len(grid),len(grid[0])
    for c in range(w):
        if grid[h-1][c] != 5: continue
        anchors=[(r,grid[r][c]) for r in range(h) if grid[r][c]!=0]
        for (a,va),(b,vb) in zip(anchors,anchors[1:]):
            # The upper/lower ray colors each location according to nearest seed;
            # ties are resolved toward the lower seed, as in the demonstrations.
            for r in range(a+1,b):
                out[r][c]=va if r-a < b-r else vb
        for r in range(anchors[0][0]): out[r][c]=anchors[0][1]
        for r in range(anchors[-1][0]+1,h): out[r][c]=anchors[-1][1]
    return out
